def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the solid divider and combine the equal panels on either side.
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != 0:
            a, b = grid[:r], grid[r+1:]
            if len(a) == len(b) and a:
                return [[2 if x != 0 and y != 0 else 0 for x, y in zip(ar, br)] for ar, br in zip(a, b)]
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1 and col[0] != 0:
            left = [row[:c] for row in grid]
            right = [row[c+1:] for row in grid]
            if c == w-c-1 and c > 0:
                return [[2 if x != 0 and y != 0 else 0 for x, y in zip(ar, br)] for ar, br in zip(left, right)]
    raise ValueError('no centered solid divider with equal panels')
